"""Source evidence for the saved scan countdown and its conditional stack ownership."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xA3D6,0xA3E2,'code','Nome del primo argomento: chiamante verificato del salvataggio B'),(0xA9DF,0xAA10,'code','Scarico della parola: ritorno a capo prima dei glifi'),(0xC363,0xC37D,'code','Pulizia della riga: spazio e chiamata al renderer'),(0xC388,0xC3E4,'code','Glifo: B della scansione salvato separatamente dal B del chiamante')]
notes={0xA3DE:'Chiamante verificato del prefisso qualificato CLIMB INTO/TAKE OFF: lo scarico passa da A745/A751 a D3E8 con frame5D2C. Il wrap porta il glifo della pulizia a frame5D26. Nessuna proprietà su un chiamante arbitrario.',0xA9EB:'Il CR viene prima della parola troppo lunga. C363 pulisce la riga e fornisce il glifo spazio: una sola istruzione di output può quindi lasciare il residuo di un’intera pulizia.',0xA9F5:'B del chiamante è la lunghezza rimanente della parola. È distinto dal B interno, che C399 reinizializza a8; nel frame5D20 questo byte fisico conserva il B del chiamante, non1.',0xC363:'Inizio pulizia dell’ultima riga. Il cursore della colonna35 dà shift7; il valore diB non si deduce da quel cursore.',0xC374:'CALL al renderer: il frame5D26 del percorso osservato lascia BC della scansione a5D1C/5D1D. Il salvataggio del registroC era già ricostruito; il byteB è verificato indipendentemente.',0xC389:'Salva il BC del chiamante prima del disegno. Frame5D20: B a5D1D dipende dal conteggio fornito. Le prove usano3 e7 e non installano1 su ogni glifo.',0xC38B:'Con frame5D24 il byte fisico5D1D è H dell’indirizzo video, nonB. Viene calcolato da riga e colonna come nel renderer esistente.',0xC399:'B=8: il renderer visita otto righe del font, indipendentemente dal B del chiamante salvato prima.',0xC39C:'PUSH BC precede il decremento DJNZ. Ultimo valore salvato: B=1, non0. Con frame5D26 B occupa5D1D. Con shift0 questo è l’ultimo store BC.',0xC39D:'Salva AF della scansione. Con frame5D28 il byte fisico5D1D è A=glyph[7], che può essere nonzero per q. Non è un conteggio universale.',0xC3B7:'Con shift nonzero ripete PUSH BC dopo avere ripristinato BC. B è ancora il contatore della scansione; il cambio in FF/lo shift del secondo byte non sono il valore salvato. Ultimo writer naturale osservato da riportare dal probe, non dal solo byte vicino5D1C.',0xC3D2:'DJNZ avviene dopo i salvataggi: raggiunge0 per uscire, ma non salva quello0. Il modello deriva il residuo dalla struttura del ciclo a8 scansioni.',0xC3D6:'Ripristina il BC originale del chiamante; i residui salvati più in basso non sono cancellati. Il campo resta proprietario soltanto nei contesti con ABI e profondità noti.'}
fields={0xC388:[['5D1D','B salvato con frame5D26','Ultimo PUSH BC dell’ottava scansione:1, perché DJNZ segue il salvataggio. Non è una costante globale del gioco'],['Altri frame','sei ruoli distinti','5D1E:A del chiamante;5D20:B del chiamante;5D22:D del descrittore;5D24:H video;5D26:B scansione;5D28:A font.5D2A/2C non raggiungono la cella'],['Proprietà','indipendente e condizionata','GO TO verificato preserva il salvataggio AF/BC se non lo raggiunge. Chiamanti sconosciuti revocano; old save assenti restano sconosciuti'],['5D1E','non introdotto','Non ricostruire il byte adiacente per estensione del presente contratto']]}

lines=['; Analisi offline con riassellaggio del payload; nessuna CPU nel motore JS.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  op,n=disassemble(m,at);assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n;count+=1
root=p/'sherlock-js/results/glyph-count';root.mkdir(exist_ok=True)
(root/'glyph-count.asm').write_text('\n'.join(lines)+'\n')
(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=128,**({'fields':fields[a]}if a in fields else{}))for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
